package com.smartcanteen.api;
import com.smartcanteen.domain.*; import com.smartcanteen.repo.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController { final OrderRepository orders; final MenuRepository menus; OrderController(OrderRepository o,MenuRepository m){orders=o;menus=m;} record Item(Long menuItemId,Integer quantity){} record Create(String pickupSlot,List<Item> items){} record StatusChange(Order.Status status){} @PostMapping Order create(@RequestBody Create request){Order o=new Order();o.pickupSlot=request.pickupSlot();o.customerEmail(email());o.itemSummary=request.items().stream().map(i->menus.findById(i.menuItemId()).map(m->{o.total+=m.price*i.quantity();return m.name+" x"+i.quantity();}).orElse("Unknown")).reduce((a,b)->a+", "+b).orElse("");return orders.save(o);} @GetMapping("/my") List<Order> mine(){return orders.findByCustomerEmailOrderByCreatedAtDesc(email());} @GetMapping("/kitchen") @PreAuthorize("hasAnyRole('STAFF','ADMIN')") List<Order> kitchen(){return orders.findByStatusInOrderByCreatedAtAsc(List.of(Order.Status.NEW,Order.Status.ON_STOVE,Order.Status.READY));} @PatchMapping("/{id}/status") @PreAuthorize("hasAnyRole('STAFF','ADMIN')") Order status(@PathVariable Long id,@RequestBody StatusChange s){Order o=orders.findById(id).orElseThrow();o.status=s.status();return orders.save(o);} String email(){return SecurityContextHolder.getContext().getAuthentication().getName();} }
